// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        Reverter reverter = new Reverter();

        vm.deal(depositor, amount + 1 wei);
        vm.prank(depositor);
        c.deposit{value: amount}();

        vm.deal(address(reverter), amount + 1 wei);
        vm.prank(address(reverter));
        c.deposit{value: amount}();

        vm.prank(address(reverter));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 oldBalance = 2 * amount;

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("no funds");
    }
    receive() external payable {
        revert("no funds");
    }
}
